// ?isLocationSafe@AIPlayer@@QAE_NPBUCoord3D@@PBVThingTemplate@@@Z
// partial score=0.3273 date=2026-09-28
// cl: /DNDEBUG /DWIN32 /MD /EHsc
// readable body of ?isLocationSafe@AIPlayer@@QAE_NPBUCoord3D@@PBVThingTemplate@@@Z:
// inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source/GameLogic/AI/AIPlayer.cpp
//
// AIPlayer::isLocationSafe, 0x00163030, 388 bytes.  Compiles to 393 bytes with
// 251 non-relocation differences and 9 structural differences (probe shape
// 0.941), up from the previous bank at 391/269/14 (0.871).  It is NOT exact.
//
// Identity is proved: the matched caller
// ?isSupplySourceSafe@AIPlayer@@QAE_NH@Z (AIPlayer.cpp:1006) calls it and
// symbols.csv pins the named ILT at 0x0003E504 here.  Zero Hour's AIPlayer.cpp
// :998 is the same function with an array-of-filters filter set; BFME retail
// instead builds six filters on the stack, links them with five calls to
// PartitionFilter::link (0x009F2AE0) and hands the head to
// ThePartitionManager->getClosestObject (0x009F26A0), so the link chain below
// is what retail's source said.  The body ends in `ret 8` at +0x181.
//
// ------------------------------------------------------------------ frame map
// Proved with an esp-accurate trace of the real callee ret arities
// (0x00160BE0 ret 8, 0x009F2AE0 ret 4, 0x009F26A0 ret 16) and cross-checked
// against FuncInfo 0x00DF3ABC (tools/eh_info.py 0x00163030: six unwind states,
// cleanup receivers -0x7c -0x44 -0xa0 -0x8c -0x94 -0xbc).  E is esp at
// function entry and Q = E - 0xBC is esp just after `sub esp, 0xb0`, so the
// EH funclets' `ebp - k` offsets are Q + (0xBC - k) and the six receivers land
// exactly on the six filter objects.  The local frame is exactly [Q, Q+0xB0):
//
//   Q+0x00..Q+0x17 24-byte KindOf mask temporary, reused as filterTeam
//                  (vtable 0x0109689C at +0x00, m_next +0x04, m_player +0x08,
//                   m_match +0x0C, m_affiliation 0x0A at +0x10)
//   Q+0x18        radius (fld tthing+0x70 ; fadd [AiData+0x84])
//   Q+0x1C..Q+0x27 filterInsignificant, vtable 0x010956E4, two Bools
//   Q+0x28..Q+0x2F filterAlive, vtable 0x01083B80, no field past m_next
//   Q+0x30..Q+0x3F filterPlayer, vtable 0x0109685C
//   Q+0x40..Q+0x77 filterHarvesters, out-of-line ctor 0x00160BE0
//   Q+0x78..Q+0xAF filterDozer, the same ctor
//
// The eight objects tile 0xB0 exactly, so retail performs exactly ONE stack-slot
// reuse: filterTeam (0x14 bytes) takes the 24-byte mask temporary's slot.  The
// mask's last write is at +0xB4 and the team's first at +0xF5, so the intervals
// really are disjoint.  Independent confirmations of the same map: the mask
// pointer handed to the 0x00160BE0 ctor is the same slot in both calls
// (`lea edx,[Q]` at 0x00163062 and 0x00163098); the radius is stored at Q+0x18
// and reloaded from Q+0x18 at 0x00163151; 0x00163149 re-reads the FIRST argument
// (pos) from E+4, not the second; and the -0xbc cleanup is one of the same
// one-store 0x1083B5C vtable-reset stubs (0x00160D10) as the other five, so the
// object that reuses the mask slot IS filterTeam, while the mask temporary
// itself has no cleanup at all.
//
// The +0x58 `push esi` is a mid-body SAVE of the incoming esi, not a temp: the
// false path jumps at +0x2E to +0x16B, skipping the matching `pop esi` at
// +0x16A, and `add esp, 0xBC` balances from Q-8 on that path and from Q-0xC on
// the other.  So retail keeps `this` in EDI, and the first ctor's return value
// in ESI (`mov esi, eax` at +0x7D, `push esi` at +0x111, `mov ecx, eax` at
// +0x112 for the first link's receiver).  EBX holds the zero constant.
//
// --------------------------------------------------------- filter identities
// The four small filters store their vtable as literals rather than through a
// vtable symbol.  That is deliberate: dir32_addresses.csv records
// ??_7PartitionFilterPlayer@@6B@ at 0x0109688C while retail stores
// 0x0109685C, and there is no entry at all for 0x010956E4 or 0x01083B80, so a
// vtable symbol here would be a name whose address the gate derives from this
// very body and therefore cannot check.  What is proved is the layout each
// class must have, from name_oracle's witnessed members and the EA source's
// constructor argument lists:
//
//   0x0109686C  vtable_lookup ties this vtable to PartitionFilterRejectByKindOf
//               (symbols.csv note on ??1PartitionFilterRejectByKindOf@@MAE@XZ),
//               and the landed ctor is
//               ??0Rva00160BE0VptrZeroBlockObject@@QAE@ABUVptrZeroBlock24@@0@Z --
//               two 24-byte masks by const reference, which is exactly Zero
//               Hour's PartitionFilterRejectByKindOf(const KindOfMaskType &,
//               const KindOfMaskType &) with m_mustBeSet at +0x08 and
//               m_mustBeClear at +0x20, the two offsets the ctor copies to.
//   0x0109685C  witnessed at +0x0008 m_player, +0x000c m_match -- the same
//               layout as name_oracle's PartitionFilterPlayer, and the landed
//               Rva001DCBB0Filter ctor builds that layout from an Object* by
//               storing getControllingPlayer() at +8.
//   0x010956E4  PartitionFilterInsignificantBuildings per the EA source
//               (AIPlayer.cpp:1043); its two Bools are true then false, the
//               Zero Hour (allowNonBuildings, allowInsignificant) order.
//   0x01083B80  PartitionFilterAlive per the EA source (AIPlayer.cpp:1035).
//   0x0109689C  PartitionFilterPlayerAffiliation; this one IS the
//               dir32_addresses.csv vtable, witnessed at +0x0008 m_player,
//               +0x000c m_match, +0x0010 m_affiliation.
//
// Link order, each call's `this` being the later filter and its argument the
// earlier one:  dozer <- harvesters <- insignificant <- player <- alive
// <- team.  Read straight off the five `lea ecx,[...]` receivers at +0x122,
// +0x12C, +0x136 and +0x140 and the first ctor's return in eax.
//
// The affiliation 0xA is ALLOW_ALLIES|ALLOW_NEUTRAL: Zero Hour's PlayerList.h
// gives 0x02 and 0x08, and the EA source passes exactly that expression
// (AIPlayer.cpp:1032).  The third getClosestObject argument is 3, i.e.
// FROM_BOUNDINGSPHERE_3D (PartitionManager.h:155), pushed at 0x00163055.
//
// ------------------------------------------- the one lever that moved the body
// `AiData *const aiData = TheAI->m_aiData;` as its own local, before the
// radius statement, is what finally reproduces retail's register plan.  Without
// it VC7.1 loads the AiData pointer into ECX for the fadd and then has to pick
// EDX as the zero constant for the mask; retail loads it into EAX twice
// (`mov eax,[0x12EF214]` / `mov eax,[eax+0x14]` / `fadd [eax+0x84]`), which
// frees ECX, and ECX is retail's zero constant.  That in turn is what puts the
// mask pointer in EDX (not EAX) and therefore what keeps the `or eax, 0x4000`
// live until +0x74 where retail stores it.  The named local is the only
// spelling found that does this: the plain `TheAI->m_aiData->...` chain,
// `const AI *ai = TheAI`, a `const Real &` to the value, and Zero Hour's
// two-statement radius order all keep the old allocation (390 bytes, 304-309
// diffs, shape 0.83-0.90), and `AiData *aiData` without `const` is identical to
// the winning form, so the effect is the named local and not constness.
//
// The mask spelling (memset the six dwords, then set one bit) is the one the
// matched AIPlayer::findSupplyCenter body uses (AIPlayerFindSupplyCenter.cpp,
// 886 B exact), and it is the only one that keeps retail's register-form
// `or eax, 0x4000`; a std::bitset<192> member instead emits a zeroing loop and
// a tracked-field zeroing folds the OR into a constant store.
//
// The result shape is retail's: `if (tthing == 0) return false;` followed by an
// unconditional tail.  That is the only spelling of the two that emits the
// `xor al,al` at +0x2C with the `jmp` to the epilogue and the `neg eax /
// sbb al,al / inc al` normalisation.  The previous bank used the
// `if (tthing != 0) { ... } return false;` spelling, which measures better on
// raw diffs only because its epilogue is shorter; with this body the
// early-return form is 251/0.941 against 269/0.871 for the other, so it wins on
// both counts and the historical trade-off is gone.
//
// ------------------------------------------------- what is still different
// Size 393 vs 388, and the five bytes are fully accounted for by ONE missing
// register allocation, not by any spelling of the frame:
//
//   ours  lea eax,[esp+0x5c] ; push eax   (5)   retail  push esi          (1)
//   ours  lea ecx,[esp+0x98]              (7)   retail  mov ecx, eax      (2)
//   ours  -                                  retail  mov esi, eax        (2)
//   ours  -                                  retail  push esi (at +0x58) (1)
//   ours  -                                  retail  pop  esi (at +0x16A)(1)
//                                          +8                           -4
//
// So the whole remaining size gap is the harvesters pointer: retail keeps the
// first ctor's return value in a callee-saved register, we re-derive the
// address with `lea` because VC7.1 folds `&filterHarvesters` into a frame
// constant.  Verified NOT reachable by spelling: a named `PartitionFilter *head`
// declared before the filters, between the two ctor calls, after them, or
// assigned after the harvesters ctor, with the chain written sequentially or
// nested (u1-u4, e4, e5) -- all six compile byte-identical, because VC7.1
// rematerialises the address constant.  The frame 0xC4 vs 0xB0 follows from the
// same thing plus filterTeam not taking the mask's slot, and is likewise
// unchanged by every lever tried: 6 declaration orders (team first, team last,
// harvesters/dozer first), the two radius positions, nested scopes around
// filterTeam / the first five / the two KindOf filters, two named mask locals,
// one reused named mask, a by-value mask factory, out-of-line destructors for
// all five filter classes, and the whole eh_levers set (throw() per callee,
// /EHsc-, _STLP_NO_EXCEPTIONS, nothrow delete[]) run through shape_search --
// 7 trials, no improving output.  Frame 0xC4 is exactly the sum of the eight
// object sizes with no reuse at all, so the whole 0x14 excess is the one
// missing slot reuse.
//
// The mechanical families were run on this bank as well, not only the EH ones:
// `python3 tools/shape_family_levers.py` over sib,register,bool,test,copy,store,
// loop,branch,constant,frame offers nine finite choices here (the three pairs of
// mask-dword zero stores, the four vtable-then-m_next store pairs, the two
// Insignificant Bools and the affiliation/match pair) and shape_search tried
// five of them: no improving output, the bank stays the best candidate.  That
// is consistent with the finding above: none of those families can reach the
// one thing that is left, which is a register allocation for an address VC7.1
// folds to a frame constant.
//
// One small ordering residue remains in the tail: retail loads `pos` into ECX
// at +0x149, pushes the link result and 3, then reloads the radius into EAX at
// +0x151; we reload the radius into ECX first and `pos` into EDX before
// pushing.  Same instructions, same bytes, different order.

#include <string.h>

extern "C" void *__cdecl memset(void *, int, unsigned int);
#pragma intrinsic(memset)

typedef bool Bool;
typedef int Int;
typedef unsigned int UnsignedInt;
typedef float Real;

struct Coord3D
{
	Real x;
	Real y;
	Real z;
};

class Object;
class Player;

class ThingTemplate
{
public:
	Real getBoundingCircleRadius(void) const
	{
		return *(const Real *)((const char *)this + 0x70);
	}
};

class AiData
{
public:
	char m_unmodelled000[0x84];
	Real m_supplyCenterSafeRadius;						// +0x84
};

class AI
{
public:
	char m_unmodelled000[0x14];
	AiData *m_aiData;									// +0x14
};

extern AI *TheAI;

// The 24-byte block the landed 0x00160BE0 ctor takes twice by const
// reference.  Both arguments are 192-bit KindOf masks, six dwords.
//
// The kInit/idx constructor is upstream BitFlags(BogusInitType, Int idx1)
// (inputs/reference/CnC_Generals_Zero_Hour/Generals/Code/GameEngine/Include/
// Common/BitFlags.h), whose body is m_bits.set(idx) on a std::bitset<192>.
// Modelling it on the parameter type itself keeps a mask a plain temporary of
// exactly the parameter type, so it binds to the by-reference argument with
// full-expression lifetime.
struct VptrZeroBlock24
{
	enum BogusInitType { kInit = 0 };

	unsigned int bits[6];

	VptrZeroBlock24(void)
	{
		bits[0] = 0;
		bits[1] = 0;
		bits[2] = 0;
		bits[3] = 0;
		bits[4] = 0;
		bits[5] = 0;
	}

	VptrZeroBlock24(BogusInitType, Int bit)
	{
		memset(bits, 0, sizeof(bits));
		bits[bit >> 5] |= (1U << (bit & 31));
	}
};

extern const VptrZeroBlock24 KINDOFMASK_NONE;

enum BFME_KindOfFromRetailMasks
{
	KINDOF_HARVESTER = 14,
	KINDOF_DOZER = 16
};

#define MAKE_KINDOF_MASK(k) VptrZeroBlock24(VptrZeroBlock24::kInit, (k))

// PlayerList.h relationship flags: ALLOW_ALLIES 0x02, ALLOW_NEUTRAL 0x08.
enum AllowPlayerRelationship
{
	ALLOW_ALLIES = 0x02,
	ALLOW_NEUTRAL = 0x08
};

// PartitionManager.h:155, the immediate retail pushes at 0x00163055.
enum DistanceCalculationType
{
	FROM_BOUNDINGSPHERE_2D = 2,
	FROM_BOUNDINGSPHERE_3D = 3
};

class PartitionFilter
{
public:
	PartitionFilter(void) {}
	PartitionFilter *link(PartitionFilter *next);

	unsigned int m_vptr;
	PartitionFilter *m_next;
};

// The already-matched shared ctor at 0x00160BE0 (VptrZeroPrefixBlockCtors.cpp)
// is PartitionFilterRejectByKindOf's; declared under its landed name so the
// call resolves to the existing definition, and rebased onto PartitionFilter
// here (identical vptr@0/next@4 head) so the result can call ::link().
class Rva00160BE0VptrZeroBlockObject : public PartitionFilter
{
public:
	__declspec(nothrow) Rva00160BE0VptrZeroBlockObject(
		const VptrZeroBlock24 &first, const VptrZeroBlock24 &second);
	~Rva00160BE0VptrZeroBlockObject(void)
	{
		m_vptr = 0x01083B5C;
	}

	VptrZeroBlock24 m_first;
	VptrZeroBlock24 m_second;
};

class PartitionFilterInsignificantBuildings : public PartitionFilter
{
public:
	PartitionFilterInsignificantBuildings(Bool allowNonBuildings, Bool allowInsignificant)
		: PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x010956E4;
		m_allowNonBuildings = allowNonBuildings;
		m_allowInsignificant = allowInsignificant;
	}

	~PartitionFilterInsignificantBuildings(void)
	{
		m_vptr = 0x01083B5C;
	}

	Bool m_allowNonBuildings;
	Bool m_allowInsignificant;
};

// vtable 0x0109685C, m_player +0x08, m_match +0x0C.
class PartitionFilterPlayer : public PartitionFilter
{
public:
	PartitionFilterPlayer(const Player *player, Bool match)
		: PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x0109685C;
		m_player = player;
		m_match = match;
	}

	~PartitionFilterPlayer(void)
	{
		m_vptr = 0x01083B5C;
	}

	const Player *m_player;
	Bool m_match;
};

class PartitionFilterAlive : public PartitionFilter
{
public:
	PartitionFilterAlive(void) : PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x01083B80;
	}

	~PartitionFilterAlive(void)
	{
		m_vptr = 0x01083B5C;
	}
};

class PartitionFilterPlayerAffiliation : public PartitionFilter
{
public:
	PartitionFilterPlayerAffiliation(const Player *player, UnsignedInt affiliation, Bool match)
		: PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x0109689C;
		m_player = player;
		m_match = match;
		m_affiliation = affiliation;
	}

	~PartitionFilterPlayerAffiliation(void)
	{
		m_vptr = 0x01083B5C;
	}

	const Player *m_player;
	Bool m_match;
	UnsignedInt m_affiliation;
};

class PartitionManager
{
public:
	Object *getClosestObject(const Coord3D *position, Real maxDistance,
		Int distanceCalculation, PartitionFilter *filters);
};

extern PartitionManager *ThePartitionManager;

class AIPlayer
{
public:
	Bool isLocationSafe(const Coord3D *pos, const ThingTemplate *tthing);

	char m_unmodelled000[0x0c];
	Player *m_player;									// +0x0C
};

Bool AIPlayer::isLocationSafe(const Coord3D *pos, const ThingTemplate *tthing)
{
	if (tthing == 0)
		return false;
	{
		AiData *const aiData = TheAI->m_aiData;
		Real radius = tthing->getBoundingCircleRadius() +
			aiData->m_supplyCenterSafeRadius;

		Rva00160BE0VptrZeroBlockObject filterHarvesters(
			MAKE_KINDOF_MASK(KINDOF_HARVESTER), KINDOFMASK_NONE);

		Rva00160BE0VptrZeroBlockObject filterDozer(
			MAKE_KINDOF_MASK(KINDOF_DOZER), KINDOFMASK_NONE);

		PartitionFilterInsignificantBuildings filterInsignificant(true, false);
		PartitionFilterPlayer filterPlayer(m_player, false);
		PartitionFilterAlive filterAlive;
		PartitionFilterPlayerAffiliation filterTeam(
			m_player, ALLOW_ALLIES | ALLOW_NEUTRAL, false);

		PartitionFilter *filters = filterTeam.link(
			filterAlive.link(
				filterPlayer.link(
					filterInsignificant.link(
						filterDozer.link(&filterHarvesters)))));

		Object *enemy = ThePartitionManager->getClosestObject(
			pos, radius, FROM_BOUNDINGSPHERE_3D, filters);
		return enemy == 0;
	}
}
